     1	//! The bundled templates (spec §11 G-44): every module of `tests/graphics/`
     2	//! except road map 10's six fixtures draws without a warning, with no `NaN`
     3	//! or `Infinity` in its SVG, and nothing outside the 90 % title-safe
     4	//! rectangle moves — at 1920×1080 and at 1080×1920, every fifth frame and
     5	//! the last. `project.yml` copies exactly the folder's modules.
     6	//! `GRAPHIC_TEMPLATE_PNGS=<dir>` writes frames 12, D/2 and D−8 of each, over
     7	//! opaque `#6e6e74`, for a person to look at.
     8	
     9	mod common;
    10	
    11	use std::fs;
    12	use std::time::Instant;
    13	
    14	use graphic::{rasterize, Module};
    15	use serde_json::Value;
    16	
    17	use common::{shared, BUDGET_MS, FIXTURES, GRAPHICS};
    18	
    19	const SIZES: [(u32, u32); 2] = [(1920, 1080), (1080, 1920)];
    20	const FPS: f64 = 30.0;
    21	
    22	/// The template stems: the folder's `*.js` less the fixtures, sorted.
    23	fn templates() -> Vec<String> {
    24	    let mut stems: Vec<String> = fs::read_dir(GRAPHICS)
    25	        .expect("tests/graphics")
    26	        .map(|entry| entry.expect("a directory entry").path())
    27	        .filter(|path| path.extension().is_some_and(|ext| ext == "js"))
    28	        .map(|path| path.file_stem().unwrap().to_string_lossy().into_owned())
    29	        .filter(|stem| !FIXTURES.contains(&stem.as_str()))
    30	        .collect();
    31	    stems.sort();
    32	    assert!(!stems.is_empty(), "no template in {GRAPHICS}");
    33	    stems
    34	}
    35	
    36	fn duration(module: &Module) -> i64 {
    37	    module.meta()["durationInFrames"]
    38	        .as_i64()
    39	        .expect("a template's meta.durationInFrames")
    40	}
    41	
    42	/// One frame drawn: the BGRA, or every problem with it named.
    43	fn draw(
    44	    module: &Module,
    45	    frame: i64,
    46	    props: &Value,
    47	    (width, height): (u32, u32),
    48	) -> Result<Vec<u8>, String> {
    49	    let name = module.name();
    50	    let ctx = common::ctx(frame, FPS, duration(module), width, height);
    51	    let at = format!("{name} {width}x{height} frame {frame}");
    52	    let (svg, warnings) = graphic::svg(module, frame, props, &ctx, BUDGET_MS)
    53	        .map_err(|d| format!("{at}: {}", d.message))?;
    54	    if !warnings.is_empty() {
    55	        return Err(format!(
    56	            "{at}: svg warned {:?}",
    57	            common::messages(&warnings)
    58	        ));
    59	    }
    60	    for bad in ["NaN", "Infinity"] {
    61	        if svg.contains(bad) {
    62	            return Err(format!("{at}: the SVG holds {bad}"));
    63	        }
    64	    }
    65	    let stride = width as usize * 4;
    66	    let mut out = vec![0u8; stride * height as usize];
    67	    let raster = rasterize(&shared(), &svg, width, height, &mut out, stride)
    68	        .map_err(|d| format!("{at}: rasterize refused: {}", d.message))?;
    69	    if !raster.is_empty() {
    70	        return Err(format!(
    71	            "{at}: rasterize warned {:?}",
    72	            common::messages(&raster)
    73	        ));
    74	    }
    75	    Ok(out)
    76	}
    77	
    78	/// Whether pixel `(x, y)` is outside title-safe: x ∈ [0.05W, 0.95W),
    79	/// y ∈ [0.05H, 0.95H).
    80	fn outside(x: u32, y: u32, (width, height): (u32, u32)) -> bool {
    81	    x < width * 5 / 100 || x >= width * 95 / 100 || y < height * 5 / 100 || y >= height * 95 / 100
    82	}
    83	
    84	/// The first pixel outside title-safe where `a` and `b` differ.
    85	fn first_difference(a: &[u8], b: &[u8], size: (u32, u32)) -> Option<(u32, u32)> {
    86	    let (width, height) = size;
    87	    for y in 0..height {
    88	        for x in 0..width {
    89	            let at = (y as usize * width as usize + x as usize) * 4;
    90	            if outside(x, y, size) && a[at..at + 4] != b[at..at + 4] {
    91	                return Some((x, y));
    92	            }
    93	        }
    94	    }
    95	    None
    96	}
    97	
    98	/// Frame 0's alpha outside title-safe, when it is one value (0 or 255).
    99	fn border_alpha(frame0: &[u8], size: (u32, u32)) -> Result<u8, String> {
   100	    let (width, height) = size;
   101	    let mut seen: Option<u8> = None;
   102	    for y in 0..height {
   103	        for x in 0..width {
   104	            if !outside(x, y, size) {
   105	                continue;
   106	            }
   107	            let alpha = frame0[(y as usize * width as usize + x as usize) * 4 + 3];
   108	            match seen {
   109	                None => seen = Some(alpha),
   110	                Some(a) if a != alpha => {
   111	                    return Err(format!(
   112	                        "alpha {a} and {alpha} (at {x},{y}) outside title-safe"
   113	                    ))
   114	                }
   115	                _ => {}
   116	            }
   117	        }
   118	    }
   119	    match seen {
   120	        Some(a @ (0 | 255)) => Ok(a),
   121	        other => Err(format!("alpha {other:?} outside title-safe, not 0 or 255")),
   122	    }
   123	}
   124	
   125	/// Writes `frame` of `module` at `size` over opaque `#6e6e74` as an RGB PNG.
   126	fn dump(dir: &str, module: &Module, frame: i64, size: (u32, u32)) {
   127	    let (width, height) = size;
   128	    let bgra = draw(module, frame, &module.defaults(), size).unwrap_or_else(|e| panic!("{e}"));
   129	    let grey = [0x6e_u32, 0x6e, 0x74];
   130	    let rgb: Vec<u8> = bgra
   131	        .chunks_exact(4)
   132	        .flat_map(|p| {
   133	            let under = 255 - p[3] as u32;
   134	            let over = |src: u8, bg: u32| (src as u32 + (bg * under + 127) / 255).min(255) as u8;
   135	            [
   136	                over(p[2], grey[0]),
   137	                over(p[1], grey[1]),
   138	                over(p[0], grey[2]),
   139	            ]
   140	        })
   141	        .collect();
   142	    fs::create_dir_all(dir).expect("the PNG folder");
   143	    let path = format!("{dir}/{}-{width}x{height}-{frame}.png", module.name());
   144	    let file = fs::File::create(&path).expect("a PNG file");
   145	    let mut encoder = png::Encoder::new(std::io::BufWriter::new(file), width, height);
   146	    encoder.set_color(png::ColorType::Rgb);
   147	    encoder.set_depth(png::BitDepth::Eight);
   148	    let mut writer = encoder.write_header().expect("a PNG header");
   149	    writer.write_image_data(&rgb).expect("PNG data");
   150	}
   151	
   152	/// The frames sampled: 0, 5, 10, … and the last.
   153	fn sampled(duration: i64) -> Vec<i64> {
   154	    let mut frames: Vec<i64> = (0..duration).step_by(5).collect();
   155	    if frames.last() != Some(&(duration - 1)) {
   156	        frames.push(duration - 1);
   157	    }
   158	    frames
   159	}
   160	
   161	#[test]
   162	fn every_template_draws_cleanly_inside_title_safe() {
   163	    let dump_dir = std::env::var("GRAPHIC_TEMPLATE_PNGS").ok();
   164	    let mut failures = Vec::new();
   165	    for stem in templates() {
   166	        let module = common::module(&stem);
   167	        let props = module.defaults();
   168	        let d = duration(&module);
   169	        for size in SIZES {
   170	            let mut times = Vec::new();
   171	            let mut frame0: Option<Vec<u8>> = None;
   172	            for frame in sampled(d) {
   173	                let started = Instant::now();
   174	                let drawn = draw(&module, frame, &props, size);
   175	                times.push(started.elapsed().as_secs_f64() * 1000.0);
   176	                let bgra = match drawn {
   177	                    Ok(bgra) => bgra,
   178	                    Err(e) => {
   179	                        failures.push(e);
   180	                        continue;
   181	                    }
   182	                };
   183	                match &frame0 {
   184	                    None => {
   185	                        if let Err(e) = border_alpha(&bgra, size) {
   186	                            failures.push(format!("{stem} {size:?} frame 0: {e}"));
   187	                        }
   188	                        frame0 = Some(bgra);
   189	                    }
   190	                    Some(first) => {
   191	                        if let Some((x, y)) = first_difference(first, &bgra, size) {
   192	                            failures.push(format!(
   193	                                "{stem} {size:?} frame {frame}: pixel ({x}, {y}) outside title-safe differs from frame 0"
   194	                            ));
   195	                        }
   196	                    }
   197	                }
   198	            }
   199	            if size == SIZES[0] {
   200	                times.sort_by(|a, b| a.partial_cmp(b).unwrap());
   201	                let p95 = times[((times.len() as f64 * 0.95).ceil() as usize).max(1) - 1];
   202	                println!("{stem}: p95 svg+rasterize {p95:.2} ms at 1920x1080");
   203	            }
   204	            if let Some(dir) = &dump_dir {
   205	                for frame in [12, d / 2, d - 8] {
   206	                    dump(dir, &module, frame, size);
   207	                }
   208	            }
   209	        }
   210	    }
   211	    assert!(failures.is_empty(), "{}", failures.join("\n"));
   212	}
   213	
   214	#[test]
   215	fn degenerate_props_draw_cleanly() {
   216	    let cases = [
   217	        ("line-chart", serde_json::json!({"values": "5"})),
   218	        ("donut-chart", serde_json::json!({"values": "0, 0"})),
   219	        ("gauge", serde_json::json!({"min": 0, "max": 0, "value": 0})),
   220	    ];
   221	    let mut failures = Vec::new();
   222	    for (stem, overrides) in cases {
   223	        let module = common::module(stem);
   224	        let mut props = module.defaults();
   225	        for (key, value) in overrides.as_object().unwrap() {
   226	            props[key] = value.clone();
   227	        }
   228	        let d = duration(&module);
   229	        for size in SIZES {
   230	            for frame in [0, d / 2, d - 1] {
   231	                if let Err(e) = draw(&module, frame, &props, size) {
   232	                    failures.push(e);
   233	                }
   234	            }
   235	        }
   236	    }
   237	    assert!(failures.is_empty(), "{}", failures.join("\n"));
   238	}
