   178	                    Err(e) => {
   179	                        failures.push(e);
   180	                        continue;
   181	                    }
   182	                };
   183	                match &frame0 {
   184	                    None => {
   185	                        if let Err(e) = border_alpha(&bgra, size) {
   186	                            failures.push(format!("{stem} {size:?} frame 0: {e}"));
   187	                        }
   188	                        frame0 = Some(bgra);
   189	                    }
   190	                    Some(first) => {
   191	                        if let Some((x, y)) = first_difference(first, &bgra, size) {
   192	                            failures.push(format!(
   193	                                "{stem} {size:?} frame {frame}: pixel ({x}, {y}) outside title-safe differs from frame 0"
   194	                            ));
   195	                        }
   196	                    }
   197	                }
   198	            }
   199	            if size == SIZES[0] {
   200	                times.sort_by(|a, b| a.partial_cmp(b).unwrap());
   201	                let p95 = times[((times.len() as f64 * 0.95).ceil() as usize).max(1) - 1];
   202	                println!("{stem}: p95 svg+rasterize {p95:.2} ms at 1920x1080");
   203	            }
   204	            if let Some(dir) = &dump_dir {
   205	                for frame in [12, d / 2, d - 8] {
   206	                    dump(dir, &module, frame, size);
   207	                }
   208	            }
   209	        }
   210	    }
   211	    assert!(failures.is_empty(), "{}", failures.join("\n"));
   212	}
