 39	export function render(frame, props, ctx) {
 40	  const u = Math.min(ctx.width, ctx.height) / 1080;
 41	  const D = ctx.durationInFrames;
 42	  const safeX = ctx.width * 0.05;
 43	  const safeY = ctx.height * 0.05;
 44	  const safeW = ctx.width * 0.9;
 45	  const safeH = ctx.height * 0.9;
 46	  const comment = props.kind === "comment";
 47	  const margin = 50 * u;
 48	  const pad = 26 * u;
 49	  const avatar = 84 * u;
 50	  const handleFont = { family: "Montserrat", size: 36 * u, weight: 800 };
 51	  const textFont = { family: "Montserrat", size: 32 * u, weight: 800 };
 52	  const count = Math.max(0, Math.round(props.count));
 53	  const countSize = fitText(formatNumber(count + 1), 220 * u, { family: "IBM Plex Mono", weight: 500 },
 54	    { min: 10 * u, max: 34 * u });
 55	  const countFont = { family: "IBM Plex Mono", size: countSize, weight: 500 };
 56	  const cardMax = Math.min(safeW - 2 * margin, 760 * u);
 57	  const g = 48 * u;
 58	  const countW = measureText(formatNumber(count + 1), countFont).width;
 59	  const sideW = g + 14 * u + countW;
 60	  const gapW = 56 * u;
 61	  const textMax = Math.max(60 * u, cardMax - 2 * pad - avatar - 24 * u - gapW - sideW);
 62	  const handleSize = props.handle ? Math.min(handleFont.size, fitText(props.handle, textMax, handleFont,
 63	    { min: 10 * u, max: handleFont.size })) : handleFont.size;
 64	  const lines = comment && props.text.trim() ? wrapText(props.text, textMax, textFont).slice(0, 3) : [];
 65	  const handleW = measureText(props.handle, { family: "Montserrat", size: handleSize, weight: 800 }).width;
 66	  const linesW = Math.max(0, ...lines.map((l) => measureText(l, textFont).width));
 67	  const textW = Math.max(handleW, linesW, 160 * u);
 68	  const cardW = 2 * pad + avatar + 24 * u + textW + gapW + sideW;
 69	  const cardH = Math.max(avatar + 2 * pad, 2 * pad + handleSize + (lines.length ? 14 * u + lines.length * textFont.size * 1.25 : 0));
 70	  const right = props.position.endsWith("right");
 71	  const bottom = props.position.startsWith("bottom");
 72	  const x = right ? safeX + safeW - margin - cardW : safeX + margin;
 73	  const y0 = bottom ? safeY + safeH - margin - cardH : safeY + margin;
 74	  const enter = spring({ frame, fps: ctx.fps, stiffness: 150, damping: 16 });
 75	  const leave = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
 76	  const y = y0 + (1 - Math.min(1, enter)) * 30 * u + leave * 30 * u;
 77	  const a = Math.max(0, Math.min(1, enter * 1.5)) * (1 - leave);
 78	  const popAt = 18;
 79	  const pop = interpolate(frame, [popAt, popAt + 6, popAt + 14], [0, 1.3, 1], { easing: Easing.outCubic, clamp: true });
 80	  const ticked = frame >= popAt + 6 ? count + 1 : count;
 81	  const ax = x + pad + avatar / 2;
 82	  const ay = y + cardH / 2;
 83	  const tx = x + pad + avatar + 24 * u;
 84	  const textBlock = handleSize + (lines.length ? 14 * u + lines.length * textFont.size * 1.25 : 0);
 85	  const handleY = y + (cardH - textBlock) / 2 + handleSize * 0.8;
 86	  let body = `<text x="${tx}" y="${handleY}" font-family="Montserrat" font-weight="800" font-size="${handleSize}"
 87	    fill="#ffffff" fill-opacity="${a}">${escapeXml(props.handle)}</text>`;
 88	  lines.forEach((line, i) => {
 89	    body += `<text x="${tx}" y="${handleY + 14 * u + (i + 1) * textFont.size * 1.25}" font-family="Montserrat"
 90	      font-weight="800" font-size="${textFont.size}" fill="#d8d8e0" fill-opacity="${a}">${escapeXml(line)}</text>`;
 91	  });
 92	  const gx = x + cardW - pad - sideW + g / 2;
 93	  const gy = y + cardH / 2;
 94	  const divX = tx + textW + gapW / 2;
 95	  return svg(ctx, `
 96	    <rect x="${x}" y="${y}" width="${cardW}" height="${cardH}" rx="${18 * u}" fill="#101014" fill-opacity="${0.9 * a}"/>
 97	    <circle cx="${ax}" cy="${ay}" r="${avatar / 2}" fill="#3a3a44" fill-opacity="${a}"/>
 98	    <circle cx="${ax}" cy="${ay - avatar * 0.1}" r="${avatar * 0.17}" fill="#9a9aa6" fill-opacity="${a}"/>
 99	    <path d="M ${ax - avatar * 0.3} ${ay + avatar * 0.33} C ${ax - avatar * 0.3} ${ay + avatar * 0.12} ${ax - avatar * 0.14} ${ay + avatar * 0.08}
100	             ${ax} ${ay + avatar * 0.08} C ${ax + avatar * 0.14} ${ay + avatar * 0.08} ${ax + avatar * 0.3} ${ay + avatar * 0.12}
101	             ${ax + avatar * 0.3} ${ay + avatar * 0.33} Z" fill="#9a9aa6" fill-opacity="${a}"/>
102	    ${body}
103	    <line x1="${divX}" y1="${y + 22 * u}" x2="${divX}" y2="${y + cardH - 22 * u}" stroke="#ffffff"
104	          stroke-opacity="${0.12 * a}" stroke-width="${2 * u}"/>
105	    ${pop > 0.001 ? `<g transform="translate(${gx} ${gy}) scale(${pop})" fill-opacity="${a}">${glyph(props.kind, g, props.accent)}</g>` : ""}
106	    <text x="${gx + g / 2 + 14 * u}" y="${gy + countFont.size * 0.36}" font-family="IBM Plex Mono" font-weight="500"
107	          font-size="${countFont.size}" fill="#ffffff" fill-opacity="${a}">${formatNumber(ticked)}</text>`);
108	}
  1	// window-frame — a bundled template (spec §11 G-44): a window's chrome to
  2	// sit over a screen recording on the track beneath — a title bar with three
  3	// dots and a title (window) or an address field (browser), and a rounded
  4	// outline. The content area stays transparent.
  5	export const meta = {
  6	  name: "Window frame",
  7	  durationInFrames: 150,
  8	};
  9	
 10	export const schema = {
 11	  style:  { type: "enum",    default: "browser", options: ["browser", "window"] },
 12	  title:  { type: "string",  default: "Frame Job" },
 13	  url:    { type: "string",  default: "example.com" },
 14	  theme:  { type: "enum",    default: "dark", options: ["dark", "light"] },
 15	  scale:  { type: "number",  default: 0.86, min: 0.5, max: 1, step: 0.01 },
 16	  shadow: { type: "boolean", default: true },
 17	  accent: { type: "color",   default: "#ff5a36" },
 18	};
 19	
 20	export function render(frame, props, ctx) {
 21	  const u = Math.min(ctx.width, ctx.height) / 1080;
 22	  const D = ctx.durationInFrames;
 23	  const dark = props.theme !== "light";
 24	  const bar = dark ? "#2a2a31" : "#e9e9ee";
 25	  const edge = dark ? "#4a4a54" : "#c4c4cc";
 26	  const field = dark ? "#1b1b20" : "#ffffff";
 27	  const ink = dark ? "#e8e8ee" : "#2a2a31";
 28	  const faint = dark ? "#8a8a96" : "#8a8a96";
 29	  const scale = Math.max(0.5, Math.min(1, props.scale));
 30	  const safeW = ctx.width * 0.9;
 31	  const safeH = ctx.height * 0.9;
 32	  const w = safeW * scale;
 33	  const h = safeH * scale;
 34	  const x = (ctx.width - w) / 2;
 35	  const y = (ctx.height - h) / 2;
 36	  const r = 12 * u;
 37	  const barH = 64 * u;
 38	  const enter = spring({ frame, fps: ctx.fps, stiffness: 120, damping: 17 });
 39	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
 40	  const rise = (1 - enter) * 30 * u;
 41	  const grow = 0.96 + 0.04 * enter;
 42	  const alpha = Math.max(0, Math.min(1, enter * 1.6)) * out;
 43	  const cx = ctx.width / 2;
 44	  const cy = ctx.height / 2;
 45	  // The shadow is kept inside title-safe: it is only as wide as the margin around the window allows.
 46	  const margin = Math.min((safeW - w) / 2, (safeH - h) / 2);
 47	  const blur = Math.min(26 * u, margin / 2.2);
 48	
 49	  let dots = "";
 50	  ["#ff5f57", "#febc2e", "#28c840"].forEach((colour, i) => {
 51	    const s = spring({ frame: frame - 8 - i * 4, fps: ctx.fps, stiffness: 260, damping: 12 });
 52	    if (s > 0.001) {
 53	      dots += `<circle cx="${x + 32 * u + i * 26 * u}" cy="${y + barH / 2}" r="${8 * u * s}" fill="${colour}" fill-opacity="${alpha}"/>`;
 54	    }
 55	  });
 56	  const uiFont = { family: "Source Sans 3", size: 26 * u, weight: 600 };
 57	  let middle = "";
 58	  const left = x + 130 * u;
 59	  const room = w - 2 * 130 * u;
 60	  if (props.style === "window") {
 61	    const size = Math.min(uiFont.size, fitText(props.title, room, uiFont, { min: 8 * u, max: uiFont.size }));
 62	    middle = `<text x="${cx}" y="${y + barH / 2 + size * 0.35}" text-anchor="middle" font-family="'Source Sans 3'"
 63	                    font-weight="600" font-size="${size}" fill="${ink}" fill-opacity="${alpha}">${escapeXml(props.title)}</text>`;
 64	  } else {
 65	    const fieldW = Math.min(room - 90 * u, Math.max(360 * u, w * 0.5));
 66	    const fieldH = 38 * u;
 67	    const fx = cx - fieldW / 2;
 68	    const fy = y + (barH - fieldH) / 2;
 69	    const size = Math.min(uiFont.size, fitText(props.url, fieldW - 90 * u, uiFont, { min: 8 * u, max: uiFont.size }));
 70	    const nav = (dx, dir) => {
 71	      const nx = left + dx;
 72	      const ny = y + barH / 2;
 73	      const k = 8 * u * dir;
 74	      return `<path d="M ${nx + k} ${ny - 8 * u} L ${nx - k} ${ny} L ${nx + k} ${ny + 8 * u}" fill="none" stroke="${faint}"
 75	                    stroke-opacity="${alpha}" stroke-width="${3 * u}" stroke-linecap="round" stroke-linejoin="round"/>`;
 76	    };
 77	    const lx = fx + 26 * u;
 78	    const ly = fy + fieldH / 2;
 79	    middle = `${nav(0, 1)}${nav(36 * u, -1)}
 80	      <rect x="${fx}" y="${fy}" width="${fieldW}" height="${fieldH}" rx="${fieldH / 2}" fill="${field}"
 81	            fill-opacity="${alpha}" stroke="${props.accent}" stroke-opacity="${alpha}" stroke-width="${2.5 * u}"/>
 82	      <rect x="${lx - 7 * u}" y="${ly - 3 * u}" width="${14 * u}" height="${11 * u}" rx="${2 * u}" fill="${faint}" fill-opacity="${alpha}"/>
 83	      <path d="M ${lx - 4.5 * u} ${ly - 3 * u} v ${-3 * u} a ${4.5 * u} ${4.5 * u} 0 0 1 ${9 * u} 0 v ${3 * u}" fill="none"
 84	            stroke="${faint}" stroke-opacity="${alpha}" stroke-width="${2 * u}"/>
 85	      <text x="${cx}" y="${ly + size * 0.35}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="600"
 86	            font-size="${size}" fill="${ink}" fill-opacity="${alpha}">${escapeXml(props.url)}</text>`;
 87	  }
 88	  // A soft shadow of thin rings outside the outline, fading outward: a filter would cost ten
 89	  // times the frame budget, and a ring never darkens the transparent content area.
 90	  let shadow = "";
 91	  if (props.shadow && blur >= 1) {
 92	    const rings = 12;
 93	    const step = (blur * 1.6) / rings;
 94	    for (let i = 0; i < rings; i++) {
 95	      const o = (i + 0.5) * step;
 96	      const fall = 1 - i / rings;
 97	      shadow += `<rect x="${x - o}" y="${y - o}" width="${w + 2 * o}" height="${h + 2 * o}" rx="${r + o}" fill="none"
 98	                       stroke="#000000" stroke-opacity="${0.16 * fall * fall * alpha}" stroke-width="${step}"/>`;
 99	    }
100	  }
101	  // Opacity per element, so no frame isolates a window-sized layer.
102	  return svg(ctx, `
103	    <g transform="translate(${cx} ${cy + rise}) scale(${grow}) translate(${-cx} ${-cy})">
104	      ${shadow}
105	      <path d="M ${x} ${y + barH} v ${-(barH - r)} a ${r} ${r} 0 0 1 ${r} ${-r} h ${w - 2 * r} a ${r} ${r} 0 0 1 ${r} ${r}
106	               v ${barH - r} Z" fill="${bar}" fill-opacity="${alpha}"/>
107	      <line x1="${x}" y1="${y + barH}" x2="${x + w}" y2="${y + barH}" stroke="${edge}" stroke-opacity="${alpha}" stroke-width="${1.5 * u}"/>
108	      <rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="none" stroke="${edge}" stroke-opacity="${alpha}" stroke-width="${2 * u}"/>
109	      ${dots}${middle}
110	    </g>`);
111	}
  1	// countdown — a bundled template (spec §11 G-44): a timer counting from
  2	// `from` to `to` one step a second (up when `to` is greater), its digits
  3	// pulsing on each tick inside a ring that empties or fills, and a flash at
  4	// the end.
  5	export const meta = {
  6	  name: "Countdown",
  7	  durationInFrames: 330,
  8	};
  9	
 10	export const schema = {
 11	  from:   { type: "number",  default: 10 },
 12	  to:     { type: "number",  default: 0 },
 13	  format: { type: "enum",    default: "m:ss", options: ["seconds", "m:ss", "h:mm:ss"] },
 14	  label:  { type: "string",  default: "Starting in" },
 15	  ring:   { type: "boolean", default: true },
 16	  accent: { type: "color",   default: "#ff5a36" },
 17	};
 18	
 19	function clock(n, format) {
 20	  const sign = n < 0 ? "-" : "";
 21	  const s = Math.abs(n);
 22	  const two = (v) => String(v).padStart(2, "0");
 23	  if (format === "seconds") return sign + s;
 24	  if (format === "h:mm:ss") return `${sign}${Math.floor(s / 3600)}:${two(Math.floor(s / 60) % 60)}:${two(s % 60)}`;
 25	  return `${sign}${Math.floor(s / 60)}:${two(s % 60)}`;
 26	}
 27	
 28	export function render(frame, props, ctx) {
 29	  const u = Math.min(ctx.width, ctx.height) / 1080;
 30	  const D = ctx.durationInFrames;
 31	  const from = Math.round(props.from);
 32	  const to = Math.round(props.to);
 33	  const steps = Math.abs(to - from);
 34	  const t = Math.max(0, ctx.time);
 35	  const ticked = Math.min(steps, Math.floor(t));
 36	  const n = to < from ? from - ticked : from + ticked;
 37	  const done = t >= steps;
 38	  const cx = ctx.width / 2;
 39	  const cy = ctx.height / 2;
 40	  const R = 300 * u;
 41	  const thick = 22 * u;
 42	  const enter = spring({ frame, fps: ctx.fps, stiffness: 140, damping: 15 });
 43	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
 44	  const local = t - Math.floor(t);
 45	  const pulse = done && t - steps > 0.3 ? 1 : interpolate(local, [0, 0.3], [1.08, 1], { easing: Easing.outCubic, clamp: true });
 46	  const left = Math.max(0, Math.min(1, 1 - t / Math.max(1, steps)));
 47	  const ringShown = to < from ? left : 1 - left;
 48	  const text = clock(n, props.format);
 49	  const widest = clock(from, props.format).length >= clock(to, props.format).length
 50	    ? clock(from, props.format) : clock(to, props.format);
 51	  const digitSize = fitText(widest.replace(/[0-9]/g, "0"), R * 1.45, { family: "IBM Plex Mono", weight: 500 },
 52	    { min: 12 * u, max: 190 * u });
 53	  const flash = done ? interpolate(t - steps, [0, 0.6], [0.85, 0], { easing: Easing.outCubic, clamp: true }) : 0;
 54	  const labelText = props.label.toUpperCase();
 55	  const labelSize = fitText(labelText, R * 1.3, { family: "Montserrat", weight: 800, letterSpacing: 5 * u },
 56	    { min: 10 * u, max: 34 * u });
 57	  const circumference = 2 * Math.PI * R;
 58	  return svg(ctx, `
 59	    <g opacity="${out * Math.min(1, enter * 1.4)}"
 60	       transform="translate(${cx} ${cy}) scale(${0.85 + 0.15 * enter}) translate(${-cx} ${-cy})">
 61	      <circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="#101014" fill-opacity="0.82"/>
 62	      ${flash > 0 ? `<circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="${props.accent}" fill-opacity="${flash}"/>` : ""}
 63	      ${props.ring ? `
 64	      <circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#ffffff" stroke-opacity="0.12" stroke-width="${thick}"/>
 65	      ${ringShown > 0.0005 ? `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="${props.accent}"
 66	              stroke-width="${thick}" stroke-linecap="round" stroke-dasharray="${circumference * ringShown} ${circumference}"
 67	              transform="rotate(-90 ${cx} ${cy})"/>` : ""}` : ""}
 68	      <text x="${cx}" y="${cy - digitSize * 0.62}" text-anchor="middle" font-family="Montserrat" font-weight="800"
 69	            font-size="${labelSize}" letter-spacing="${5 * u}" fill="#d8d8e0">${escapeXml(labelText)}</text>
 70	      <g transform="translate(${cx} ${cy + digitSize * 0.12}) scale(${pulse})">
 71	        <text x="0" y="${digitSize * 0.35}" text-anchor="middle" font-family="IBM Plex Mono" font-weight="500"
 72	              font-size="${digitSize}" fill="#ffffff">${escapeXml(text)}</text>
 73	      </g>
 74	    </g>`);
 75	}

