 39	export function render(frame, props, ctx) {
 40	  const u = Math.min(ctx.width, ctx.height) / 1080;
 41	  const D = ctx.durationInFrames;
 42	  const safeX = ctx.width * 0.05;
 43	  const safeY = ctx.height * 0.05;
 44	  const safeW = ctx.width * 0.9;
 45	  const safeH = ctx.height * 0.9;
 46	  const comment = props.kind === "comment";
 47	  const margin = 50 * u;
 48	  const pad = 26 * u;
 49	  const avatar = 84 * u;
 50	  const handleFont = { family: "Montserrat", size: 36 * u, weight: 800 };
 51	  const textFont = { family: "Montserrat", size: 32 * u, weight: 800 };
 52	  const count = Math.max(0, Math.round(props.count));
 53	  const countSize = fitText(formatNumber(count + 1), 220 * u, { family: "IBM Plex Mono", weight: 500 },
 54	    { min: 10 * u, max: 34 * u });
 55	  const countFont = { family: "IBM Plex Mono", size: countSize, weight: 500 };
 56	  const cardMax = Math.min(safeW - 2 * margin, 760 * u);
 57	  const g = 48 * u;
 58	  const countW = measureText(formatNumber(count + 1), countFont).width;
 59	  const sideW = g + 14 * u + countW;
 60	  const gapW = 56 * u;
 61	  const textMax = Math.max(60 * u, cardMax - 2 * pad - avatar - 24 * u - gapW - sideW);
 62	  const handleSize = props.handle ? Math.min(handleFont.size, fitText(props.handle, textMax, handleFont,
 63	    { min: 10 * u, max: handleFont.size })) : handleFont.size;
 64	  const lines = comment && props.text.trim() ? wrapText(props.text, textMax, textFont).slice(0, 3) : [];
 65	  const handleW = measureText(props.handle, { family: "Montserrat", size: handleSize, weight: 800 }).width;
 66	  const linesW = Math.max(0, ...lines.map((l) => measureText(l, textFont).width));
 67	  const textW = Math.max(handleW, linesW, 160 * u);
 68	  const cardW = 2 * pad + avatar + 24 * u + textW + gapW + sideW;
 69	  const cardH = Math.max(avatar + 2 * pad, 2 * pad + handleSize + (lines.length ? 14 * u + lines.length * textFont.size * 1.25 : 0));
 70	  const right = props.position.endsWith("right");
 71	  const bottom = props.position.startsWith("bottom");
 72	  const x = right ? safeX + safeW - margin - cardW : safeX + margin;
 73	  const y0 = bottom ? safeY + safeH - margin - cardH : safeY + margin;
 74	  const enter = spring({ frame, fps: ctx.fps, stiffness: 150, damping: 16 });
 75	  const leave = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
 76	  const y = y0 + (1 - Math.min(1, enter)) * 30 * u + leave * 30 * u;
 77	  const a = Math.max(0, Math.min(1, enter * 1.5)) * (1 - leave);
 78	  const popAt = 18;
 79	  const pop = interpolate(frame, [popAt, popAt + 6, popAt + 14], [0, 1.3, 1], { easing: Easing.outCubic, clamp: true });
 80	  const ticked = frame >= popAt + 6 ? count + 1 : count;
 81	  const ax = x + pad + avatar / 2;
 82	  const ay = y + cardH / 2;
 83	  const tx = x + pad + avatar + 24 * u;
 84	  const textBlock = handleSize + (lines.length ? 14 * u + lines.length * textFont.size * 1.25 : 0);
