     1	// subscribe-button — a bundled template (spec §11 G-44): a pill button with
     2	// a play glyph pops in, a cursor glides to it and clicks (a squash and a
     3	// ripple), the button turns to its done state with a check, and a bell pops
     4	// in beside it and rings after a second click. Every glyph is a generic
     5	// vector shape.
     6	export const meta = {
     7	  name: "Subscribe button",
     8	  durationInFrames: 150,
     9	};
    10	
    11	export const schema = {
    12	  label:     { type: "string",  default: "SUBSCRIBE" },
    13	  doneLabel: { type: "string",  default: "SUBSCRIBED" },
    14	  bell:      { type: "boolean", default: true },
    15	  position:  { type: "enum",    default: "bottom", options: ["bottom", "center", "top"] },
    16	  accent:    { type: "color",   default: "#e5322d" },
    17	};
    18	
    19	const DONE = "#3a3a40";
    20	
    21	function bellPath(g) {
    22	  const s = (v) => v * g;
    23	  return `M ${s(-0.36)} ${s(0.26)} C ${s(-0.26)} ${s(0.14)} ${s(-0.28)} ${s(0.02)} ${s(-0.28)} ${s(-0.12)}
    24	    C ${s(-0.28)} ${s(-0.34)} ${s(-0.15)} ${s(-0.46)} 0 ${s(-0.46)} C ${s(0.15)} ${s(-0.46)} ${s(0.28)} ${s(-0.34)} ${s(0.28)} ${s(-0.12)}
    25	    C ${s(0.28)} ${s(0.02)} ${s(0.26)} ${s(0.14)} ${s(0.36)} ${s(0.26)} Z`;
    26	}
    27	
    28	export function render(frame, props, ctx) {
    29	  const u = Math.min(ctx.width, ctx.height) / 1080;
    30	  const D = ctx.durationInFrames;
    31	  const safeY = ctx.height * 0.05;
    32	  const safeW = ctx.width * 0.9;
    33	  const safeH = ctx.height * 0.9;
    34	  const click = Math.round(D * 0.4);
    35	  const done = frame >= click + 3;
    36	  const btnH = 96 * u;
    37	  const font = { family: "Montserrat", size: 38 * u, weight: 900, letterSpacing: 2 * u };
    38	  const room = safeW - 2 * 60 * u - (props.bell ? btnH + 24 * u : 0) - btnH * 1.1;
    39	  const sizeOf = (t) => Math.min(font.size, fitText(t, room, font, { min: 10 * u, max: font.size }));
    40	  const widthOf = (t, size) => measureText(t, Object.assign({}, font, { size })).width;
    41	  const sizeA = sizeOf(props.label);
    42	  const sizeB = sizeOf(props.doneLabel);
    43	  const wA = btnH * 0.95 + widthOf(props.label, sizeA) + 44 * u;
    44	  const wB = btnH * 0.95 + widthOf(props.doneLabel, sizeB) + 44 * u;
    45	  const morph = interpolate(frame, [click + 2, click + 12], [0, 1], { easing: Easing.inOutCubic, clamp: true });
    46	  const btnW = wA + (wB - wA) * morph;
    47	  const bellD = btnH;
    48	  const groupW = Math.max(wA, wB) + (props.bell ? 24 * u + bellD : 0);
    49	  const margin = 70 * u;
    50	  const cy = props.position === "top" ? safeY + margin + btnH / 2
    51	    : props.position === "center" ? ctx.height / 2
    52	    : safeY + safeH - margin - btnH / 2 - 40 * u;
    53	  const gx = ctx.width / 2 - groupW / 2;
    54	  const bx = gx;
    55	  const bcx = bx + btnW / 2;
    56	  const pop = spring({ frame, fps: ctx.fps, stiffness: 180, damping: 12 });
    57	  const squash = interpolate(frame, [click - 2, click + 1, click + 7], [1, 0.94, 1], { clamp: true });
    58	  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
    59	  const fill = done ? DONE : props.accent;
    60	  const label = done ? props.doneLabel : props.label;
    61	  const size = done ? sizeB : sizeA;
    62	  const ix = bx + btnH * 0.55;
    63	  const g = btnH * 0.42;
    64	  const icon = done
    65	    ? `<path d="M ${ix - g * 0.38} ${cy} L ${ix - g * 0.1} ${cy + g * 0.28} L ${ix + g * 0.4} ${cy - g * 0.3}" fill="none"
    66	             stroke="#ffffff" stroke-width="${7 * u}" stroke-linecap="round" stroke-linejoin="round"/>`
    67	    : `<path d="M ${ix - g * 0.3} ${cy - g * 0.42} L ${ix + g * 0.45} ${cy} L ${ix - g * 0.3} ${cy + g * 0.42} Z" fill="#ffffff"
    68	             stroke="#ffffff" stroke-width="${4 * u}" stroke-linejoin="round"/>`;
    69	  const ripple = interpolate(frame, [click, click + 16], [0, 1], { easing: Easing.outCubic, clamp: true });
    70	  const rippleOn = frame >= click && ripple < 1;
    71	  const button = `
    72	    <clipPath id="pill"><rect x="${bx}" y="${cy - btnH / 2}" width="${btnW}" height="${btnH}" rx="${btnH / 2}"/></clipPath>
    73	    <g transform="translate(${bcx} ${cy}) scale(${squash}) translate(${-bcx} ${-cy})">
    74	      <rect x="${bx}" y="${cy - btnH / 2}" width="${btnW}" height="${btnH}" rx="${btnH / 2}" fill="${fill}"/>
    75	      ${rippleOn ? `<g clip-path="url(#pill)"><circle cx="${bx + btnW * 0.62}" cy="${cy}" r="${btnW * 0.7 * ripple}"
    76	          fill="#ffffff" fill-opacity="${0.35 * (1 - ripple)}"/></g>` : ""}
    77	      ${icon}
    78	      <text x="${bx + btnH * 0.95}" y="${cy + size * 0.36}" font-family="Montserrat" font-weight="900" font-size="${size}"
    79	            letter-spacing="${2 * u}" fill="#ffffff">${escapeXml(label)}</text>
    80	    </g>`;
    81	
    82	  // The bell pops in after the first click, the cursor clicks it, and it rings.
    83	  const bellX = bx + Math.max(wA, wB) + 24 * u + bellD / 2;
    84	  const click2 = click + 26;
    85	  let bell = "";
    86	  if (props.bell) {
    87	    const bpop = spring({ frame: frame - click - 8, fps: ctx.fps, stiffness: 200, damping: 11 });
    88	    const t = (frame - click2) / ctx.fps;
    89	    const ring = frame >= click2 ? 18 * Math.exp(-3 * t) * Math.sin(t * 2 * Math.PI * 3.2) : 0;
    90	    const on = frame >= click2;
    91	    if (bpop > 0.001) {
    92	      const bg = bellD * 0.62;
    93	      bell = `<g transform="translate(${bellX} ${cy}) scale(${bpop})">
    94	        <circle cx="0" cy="0" r="${bellD / 2}" fill="${on ? props.accent : DONE}"/>
    95	        <g transform="translate(0 ${-bg * 0.08}) rotate(${ring} 0 ${-bg * 0.46})">
    96	          <path d="${bellPath(bg)}" fill="#ffffff"/>
    97	          <circle cx="0" cy="${bg * 0.36}" r="${bg * 0.1}" fill="#ffffff"/>
    98	          <circle cx="0" cy="${-bg * 0.5}" r="${bg * 0.07}" fill="#ffffff"/>
    99	        </g></g>`;
   100	    }
   101	  }
   102	
   103	  // The cursor: from the lower right inside title-safe, to the button, then the bell.
   104	  const target1x = bx + btnW * 0.62;
   105	  const target2x = bellX + bellD * 0.1;
   106	  const tipY = cy + btnH * 0.12;
   107	  const startX = Math.min(ctx.width * 0.95 - 120 * u, target1x + 380 * u);
   108	  const startY = Math.min(ctx.height * 0.95 - 120 * u, cy + 150 * u);
   109	  const glide = interpolate(frame, [10, click - 4], [0, 1], { easing: Easing.inOutCubic, clamp: true });
   110	  const hop = interpolate(frame, [click + 10, click2 - 4], [0, 1], { easing: Easing.inOutCubic, clamp: true });
   111	  let curX = startX + (target1x - startX) * glide;
   112	  let curY = startY + (tipY - startY) * glide;
   113	  if (props.bell) {
   114	    curX += (target2x - target1x) * hop;
   115	    curY += -12 * u * Math.sin(Math.PI * hop);
   116	  }
   117	  const press = frame >= click - 2 && frame < click + 4 ? 0.88
   118	    : props.bell && frame >= click2 - 2 && frame < click2 + 4 ? 0.88 : 1;
   119	  const curIn = interpolate(frame, [8, 16], [0, 1], { clamp: true });
   120	  const k = 46 * u;
   121	  const cursor = curIn > 0 ? `<g transform="translate(${curX} ${curY}) scale(${press})" opacity="${curIn}">
   122	      <path d="M 0 0 L 0 ${k} L ${k * 0.25} ${k * 0.77} L ${k * 0.42} ${k * 1.12} L ${k * 0.56} ${k * 1.05}
   123	               L ${k * 0.4} ${k * 0.71} L ${k * 0.72} ${k * 0.71} Z" fill="#ffffff" stroke="#111114"
   124	            stroke-width="${3 * u}" stroke-linejoin="round"/>
   125	    </g>` : "";
   126	  const gcx = ctx.width / 2;
   127	  const scale = pop * (1 - 0.15 * out);
   128	  return svg(ctx, `
   129	    <g opacity="${1 - out}" transform="translate(${gcx} ${cy}) scale(${scale}) translate(${-gcx} ${-cy})">
   130	      ${button}${bell}${cursor}
   131	    </g>`);
   132	}
     1	// end-screen — a bundled template (spec §11 G-44): a full card laid out for
     2	// a video's end screen — two 16:9 placeholders where the platform's video
     3	// elements go and a subscribe circle — in a row in landscape and a column in
     4	// portrait, under a title.
     5	export const meta = {
     6	  name: "End screen",
     7	  durationInFrames: 300,
     8	};
     9	
    10	export const schema = {
    11	  title:      { type: "string", default: "Watch next" },
    12	  videoA:     { type: "string", default: "Latest video" },
    13	  videoB:     { type: "string", default: "Best for you" },
    14	  subscribe:  { type: "string", default: "Subscribe" },
    15	  background: { type: "color",  default: "#0b0b10" },
    16	  accent:     { type: "color",  default: "#ff5a36" },
    17	};
    18	
    19	export function render(frame, props, ctx) {
    20	  const u = Math.min(ctx.width, ctx.height) / 1080;
    21	  const D = ctx.durationInFrames;
    22	  const W = ctx.width;
    23	  const H = ctx.height;
    24	  const landscape = W > H;
    25	  const safeX = W * 0.05;
    26	  const safeY = H * 0.05;
    27	  const safeW = W * 0.9;
    28	  const safeH = H * 0.9;
    29	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    30	  const titleSize = props.title ? fitText(props.title, safeW - 120 * u, { family: "Montserrat", weight: 900 },
    31	    { min: 16 * u, max: 84 * u }) : 0;
    32	  const labelFont = { family: "Montserrat", size: 34 * u, weight: 800 };
    33	  const gap = 48 * u;
    34	  const boxW = landscape ? W * 0.3 : W * 0.8;
    35	  const boxH = (boxW * 9) / 16;
    36	  const circleD = landscape ? boxH * 0.86 : 260 * u;
    37	  const labelH = 70 * u;
    38	  let boxes;
    39	  let circle;
    40	  let titleY;
    41	  if (landscape) {
    42	    const rowW = circleD + 2 * boxW + 2 * gap;
    43	    const rowH = boxH + labelH;
    44	    const blockH = titleSize + 70 * u + rowH;
    45	    const top = safeY + (safeH - blockH) / 2;
    46	    titleY = top + titleSize * 0.8;
    47	    const rowTop = top + titleSize + 70 * u;
    48	    const x = (W - rowW) / 2;
    49	    circle = { cx: x + circleD / 2, cy: rowTop + boxH / 2 };
    50	    boxes = [
    51	      { x: x + circleD + gap, y: rowTop, label: props.videoA },
    52	      { x: x + circleD + gap + boxW + gap, y: rowTop, label: props.videoB },
    53	    ];
    54	  } else {
    55	    const blockH = titleSize + 60 * u + 2 * (boxH + labelH) + gap + circleD + labelH;
    56	    const top = safeY + (safeH - blockH) / 2;
    57	    titleY = top + titleSize * 0.8;
    58	    const x = (W - boxW) / 2;
    59	    const first = top + titleSize + 60 * u;
    60	    boxes = [
    61	      { x, y: first, label: props.videoA },
    62	      { x, y: first + boxH + labelH + gap / 2, label: props.videoB },
    63	    ];
    64	    circle = { cx: W / 2, cy: first + 2 * (boxH + labelH) + gap + circleD / 2 };
    65	  }
    66	  const titleIn = interpolate(frame, [0, 16], [0, 1], { easing: Easing.outCubic, clamp: true });
    67	  let body = props.title ? `<text x="${W / 2}" y="${titleY + (1 - titleIn) * 20 * u}" text-anchor="middle"
    68	    font-family="Montserrat" font-weight="900" font-size="${titleSize}" fill="#ffffff"
    69	    fill-opacity="${titleIn * out}">${escapeXml(props.title)}</text>` : "";
    70	  boxes.forEach((b, i) => {
    71	    const t = spring({ frame: frame - 8 - i * 6, fps: ctx.fps, stiffness: 150, damping: 15 });
    72	    if (t <= 0.001) return;
    73	    const a = Math.min(1, t) * out;
    74	    const cx = b.x + boxW / 2;
    75	    const cy = b.y + boxH / 2;
    76	    const s = 0.9 + 0.1 * t;
    77	    const g = boxH * 0.2;
    78	    const size = Math.min(labelFont.size, fitText(b.label || " ", boxW, labelFont, { min: 10 * u, max: labelFont.size }));
    79	    body += `<g transform="translate(${cx} ${cy}) scale(${s}) translate(${-cx} ${-cy})">
    80	      <rect x="${b.x}" y="${b.y}" width="${boxW}" height="${boxH}" rx="${14 * u}" fill="#ffffff" fill-opacity="${0.06 * a}"
    81	            stroke="#ffffff" stroke-opacity="${0.55 * a}" stroke-width="${3 * u}" stroke-dasharray="${16 * u} ${10 * u}"/>
    82	      <circle cx="${cx}" cy="${cy}" r="${g}" fill="${props.accent}" fill-opacity="${a}"/>
    83	      <path d="M ${cx - g * 0.32} ${cy - g * 0.45} L ${cx + g * 0.5} ${cy} L ${cx - g * 0.32} ${cy + g * 0.45} Z"
    84	            fill="#ffffff" fill-opacity="${a}"/>
    85	      <text x="${cx}" y="${b.y + boxH + 46 * u}" text-anchor="middle" font-family="Montserrat" font-weight="800"
    86	            font-size="${size}" fill="#d8d8e0" fill-opacity="${a}">${escapeXml(b.label)}</text></g>`;
    87	  });
    88	  const pop = spring({ frame: frame - 24, fps: ctx.fps, stiffness: 190, damping: 12 });
    89	  if (pop > 0.001) {
    90	    const r = circleD / 2;
    91	    const pulse = interpolate(frame, [40, 70], [0, 1], { easing: Easing.outCubic, clamp: true });
    92	    const a = out;
    93	    const size = Math.min(labelFont.size, fitText(props.subscribe || " ", Math.max(circleD, 200 * u), labelFont,
    94	      { min: 10 * u, max: labelFont.size }));
    95	    const head = r * 0.3;
    96	    body += `<g transform="translate(${circle.cx} ${circle.cy}) scale(${pop})">
    97	      ${pulse > 0 && pulse < 1 ? `<circle cx="0" cy="0" r="${r + 26 * u * pulse}" fill="none" stroke="${props.accent}"
    98	              stroke-width="${4 * u}" stroke-opacity="${(1 - pulse) * a}"/>` : ""}
    99	      <circle cx="0" cy="0" r="${r}" fill="#ffffff" fill-opacity="${0.06 * a}" stroke="${props.accent}"
   100	              stroke-opacity="${a}" stroke-width="${5 * u}" stroke-dasharray="${16 * u} ${10 * u}"/>
   101	      <circle cx="0" cy="${-head * 0.62}" r="${head}" fill="#8a8a94" fill-opacity="${a}"/>
   102	      <path d="M ${-r * 0.5} ${r * 0.55} C ${-r * 0.5} ${r * 0.1} ${-r * 0.25} ${r * 0.0} 0 ${r * 0.0}
   103	               C ${r * 0.25} ${r * 0.0} ${r * 0.5} ${r * 0.1} ${r * 0.5} ${r * 0.55} Z" fill="#8a8a94" fill-opacity="${a}"/>
   104	      <text x="0" y="${(landscape ? boxH / 2 : r) + 46 * u}" text-anchor="middle" font-family="Montserrat" font-weight="800" font-size="${size}"
   105	            fill="#ffffff" fill-opacity="${a}">${escapeXml(props.subscribe)}</text></g>`;
   106	  }
   107	  return svg(ctx, body, { background: props.background });
   108	}
     1	// quote-card — a bundled template (spec §11 G-44): a full card with an
     2	// accent opening quote mark drawn as a vector shape, the quote's lines
     3	// fading up in turn, and a rule and attribution sliding in.
     4	export const meta = {
     5	  name: "Quote card",
     6	  durationInFrames: 150,
     7	};
     8	
     9	export const schema = {
    10	  quote:       { type: "string", default: "The best way to get started is to quit talking and begin doing.", multiline: true },
    11	  attribution: { type: "string", default: "Walt Disney" },
    12	  background:  { type: "color",  default: "#101014" },
    13	  accent:      { type: "color",  default: "#ffd60a" },
    14	};
    15	
    16	// One “6”-shaped quote half: a ball with a tail rising to the upper right, `s` tall.
    17	function mark(x, y, s) {
    18	  const r = s * 0.3;
    19	  const cx = x + r;
    20	  const cy = y + s - r;
    21	  return `<circle cx="${cx}" cy="${cy}" r="${r}"/>
    22	    <path d="M ${cx - r} ${cy} C ${cx - r} ${cy - r * 2.2} ${cx + r * 0.2} ${y + s * 0.08} ${cx + r * 1.25} ${y}
    23	             L ${cx + r * 1.25} ${y + s * 0.18} C ${cx + r * 0.25} ${y + s * 0.3} ${cx - r * 0.15} ${cy - r * 1.3} ${cx + r * 0.2} ${cy - r * 0.95} Z"/>`;
    24	}
    25	
    26	export function render(frame, props, ctx) {
    27	  const u = Math.min(ctx.width, ctx.height) / 1080;
    28	  const D = ctx.durationInFrames;
    29	  const safeY = ctx.height * 0.05;
    30	  const safeW = ctx.width * 0.9;
    31	  const safeH = ctx.height * 0.9;
    32	  const textW = safeW * 0.8;
    33	  const left = (ctx.width - textW) / 2;
    34	  const markH = 110 * u;
    35	  const attrSize = 40 * u;
    36	  const reserved = markH + 50 * u + 100 * u + attrSize + 2 * 60 * u;
    37	  let size = 84 * u;
    38	  let lines = [];
    39	  for (; size > 28 * u; size -= 4 * u) {
    40	    lines = wrapText(props.quote, textW, { family: "Montserrat", size, weight: 800 });
    41	    if (lines.length * size * 1.25 <= safeH - reserved) break;
    42	  }
    43	  if (size <= 28 * u) {
    44	    size = 28 * u;
    45	    lines = wrapText(props.quote, textW, { family: "Montserrat", size, weight: 800 });
    46	  }
    47	  const lineH = size * 1.25;
    48	  const blockH = markH + 50 * u + lines.length * lineH + 100 * u + attrSize;
    49	  const top = safeY + Math.max(60 * u, (safeH - blockH) / 2);
    50	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
    51	  const markIn = spring({ frame, fps: ctx.fps, stiffness: 160, damping: 12 });
    52	  const mx = left;
    53	  const my = top;
    54	  const mcx = mx + markH * 0.6;
    55	  const mcy = my + markH / 2;
    56	  let body = "";
    57	  lines.forEach((line, i) => {
    58	    const t = interpolate(frame, [10 + i * 6, 28 + i * 6], [0, 1], { easing: Easing.outCubic, clamp: true });
    59	    const y = top + markH + 50 * u + size * 0.9 + i * lineH + (1 - t) * 24 * u;
    60	    body += `<text x="${left}" y="${y}" font-family="Montserrat" font-weight="800" font-size="${size}" fill="#ffffff"
    61	                   fill-opacity="${t * out}">${escapeXml(line)}</text>`;
    62	  });
    63	  const endLines = 28 + lines.length * 6;
    64	  const attrIn = interpolate(frame, [endLines - 6, endLines + 14], [0, 1], { easing: Easing.outCubic, clamp: true });
    65	  const attrY = top + markH + 50 * u + lines.length * lineH + 60 * u + 40 * u;
    66	  const slide = (1 - attrIn) * -40 * u;
    67	  const attrText = props.attribution.trim() ? `— ${props.attribution}` : "";
    68	  const attrFit = attrText ? Math.min(attrSize, fitText(attrText, textW,
    69	    { family: "Montserrat", weight: 800 }, { min: 10 * u, max: attrSize })) : attrSize;
    70	  return svg(ctx, `
    71	    ${markIn > 0.001 ? `<g fill="${props.accent}" fill-opacity="${out}"
    72	       transform="translate(${mcx} ${mcy}) scale(${markIn}) translate(${-mcx} ${-mcy})">
    73	      ${mark(mx, my, markH)}${mark(mx + markH * 0.72, my, markH)}
    74	    </g>` : ""}
    75	    ${body}
    76	    ${attrIn > 0 ? `<rect x="${left + slide}" y="${attrY - attrSize - 34 * u}" width="${80 * u}" height="${6 * u}"
    77	          fill="${props.accent}" fill-opacity="${attrIn * out}"/>
    78	    <text x="${left + slide}" y="${attrY}" font-family="Montserrat" font-weight="800"
