 31	export function render(frame, props, ctx) {
 32	  const u = Math.min(ctx.width, ctx.height) / 1080;
 33	  const D = ctx.durationInFrames;
 34	  const values = props.values.split(",").map((v) => Number(v.trim())).filter((v) => isFinite(v))
 35	    .map((v) => Math.max(0, v));
 36	  const labels = props.labels.split(",").map((l) => l.trim());
 37	  const n = values.length;
 38	  const total = values.reduce((a, b) => a + b, 0);
 39	  const landscape = ctx.width > ctx.height;
 40	  const safeX = ctx.width * 0.05;
 41	  const safeY = ctx.height * 0.05;
 42	  const safeW = ctx.width * 0.9;
 43	  const safeH = ctx.height * 0.9;
 44	  const pad = 60 * u;
 45	  const innerW = safeW - 2 * pad;
 46	  const titleSize = fitText(props.title, innerW, { family: "Montserrat", weight: 900 }, { min: 12 * u, max: 64 * u });
 47	  const rowH = Math.min(78 * u, (landscape ? safeH - 300 * u : 560 * u) / Math.max(1, n));
 48	  const legendH = rowH * n;
 49	  const thick = 64 * u;
 50	  const legendW = Math.min(620 * u, innerW);
 51	  let R;
 52	  let cx;
 53	  let cy;
 54	  let legendX;
 55	  let legendY;
 56	  let blockTop;
 57	  if (landscape) {
 58	    R = Math.min((safeH - 2 * pad - titleSize - 100 * u) / 2 - thick / 2, innerW * 0.22);
 59	    blockTop = safeY + pad;
 60	    const blockW = 2 * R + thick + 140 * u + legendW;
 61	    cx = Math.max(safeX + pad, (ctx.width - blockW) / 2) + thick / 2 + R;
 62	    cy = blockTop + titleSize + 70 * u + thick / 2 + R;
 63	    legendX = cx + R + thick / 2 + 140 * u;
 64	    legendY = cy - legendH / 2;
 65	  } else {
 66	    R = innerW * 0.3;
 67	    const blockH = titleSize + 80 * u + 2 * R + thick + 90 * u + legendH;
 68	    blockTop = safeY + Math.max(pad, (safeH - blockH) / 2);
 69	    cx = ctx.width / 2;
 70	    cy = blockTop + titleSize + 80 * u + thick / 2 + R;
 71	    legendX = (ctx.width - legendW) / 2;
 72	    legendY = cy + R + thick / 2 + 90 * u;
 73	  }
 74	  const titleX = landscape ? cx - R - thick / 2 : ctx.width / 2;
 75	  const titleFits = landscape
 76	    ? Math.min(titleSize, fitText(props.title, safeX + safeW - pad - titleX, { family: "Montserrat", weight: 900 },
 77	      { min: 12 * u, max: 64 * u }))
 78	    : titleSize;
 79	  const fade = interpolate(frame, [0, 15], [0, 1], { clamp: true });
 80	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
 81	  const sweep = interpolate(frame, [8, 70], [0, 360], { easing: Easing.inOutCubic, clamp: true });
 82	  const gap = n > 1 ? 1.6 : 0;
 83	
 84	  let slices = `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#ffffff" stroke-opacity="0.08"
 85	                        stroke-width="${thick}"/>`;
 86	  let start = 0;
 87	  values.forEach((v, i) => {
 88	    const size = total > 0 ? (v / total) * 360 : 0;
 89	    const shown = Math.min(sweep, start + size) - start;
 90	    if (size > 0 && shown > gap) {
 91	      const colour = i === 0 ? props.accent : PALETTE[(i - 1) % PALETTE.length];
 92	      slices += `<path d="${arc(cx, cy, R, start + gap / 2, start + shown - gap / 2)}" fill="none"
 93	                       stroke="${colour}" stroke-width="${thick}"/>`;
 94	    }
 95	    start += size;
 96	  });
 97	
 98	  const share = total > 0 ? (values[0] / total) * 100 : 0;
 99	  const counted = share * interpolate(frame, [8, 70], [0, 1], { easing: Easing.inOutCubic, clamp: true });
100	  const percentSize = Math.min(120 * u, R * 0.62);
101	  const centre = `
102	    <text x="${cx}" y="${cy + percentSize * 0.3}" text-anchor="middle" font-family="IBM Plex Mono"
103	          font-weight="500" font-size="${percentSize}" fill="#ffffff">${Math.round(counted)}%</text>
104	    <text x="${cx}" y="${cy + percentSize * 0.3 + 52 * u}" text-anchor="middle" font-family="Montserrat"
105	          font-weight="800" font-size="${28 * u}" fill="#c8c8d0" opacity="${fade}">${escapeXml(labels[0] || "")}</text>`;
106	
107	  let legend = "";
108	  const legendFont = { family: "Montserrat", size: Math.min(36 * u, rowH * 0.5), weight: 800 };
109	  values.forEach((v, i) => {
110	    const t = spring({ frame: frame - 24 - i * 6, fps: ctx.fps, damping: 16 });
111	    if (t <= 0.001) return;
112	    const colour = i === 0 ? props.accent : PALETTE[(i - 1) % PALETTE.length];
113	    const y = legendY + rowH * i + rowH / 2;
114	    const pct = total > 0 ? `${Math.round((v / total) * 100)}%` : "0%";
115	    const sq = legendFont.size * 0.8;
116	    legend += `<g opacity="${Math.min(1, t)}" transform="translate(${(1 - Math.min(1, t)) * 30 * u} 0)">
117	      <rect x="${legendX}" y="${y - sq / 2}" width="${sq}" height="${sq}" rx="${sq * 0.2}" fill="${colour}"/>
118	      <text x="${legendX + sq + 22 * u}" y="${y + legendFont.size * 0.36}" font-family="Montserrat" font-weight="800"
119	            font-size="${legendFont.size}" fill="#ffffff">${escapeXml(labels[i] || "")}</text>
120	      <text x="${legendX + legendW}" y="${y + legendFont.size * 0.36}" text-anchor="end" font-family="IBM Plex Mono"
121	            font-weight="500" font-size="${legendFont.size}" fill="#c8c8d0">${pct}</text></g>`;
122	  });
123	
124	  return svg(ctx, `
125	    <g opacity="${out}">
126	      <text x="${titleX}" y="${blockTop + titleSize * 0.8}" text-anchor="${landscape ? "start" : "middle"}"
127	            font-family="Montserrat" font-weight="900" font-size="${titleFits}" fill="#ffffff"
128	            opacity="${fade}">${escapeXml(props.title)}</text>
129	      ${slices}${centre}${legend}
130	    </g>`, { background: "#15151b" });

